import{_ as e,o as s,c as i,ag as t}from"./chunks/framework.C9sp7nFj.js";const b=JSON.parse('{"title":"SetAxisVibraBLevel 设置抑振强度等级","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/SetAxisVibraBLevel.md","filePath":"3. 指令/5. 设置指令/SetAxisVibraBLevel.md","lastUpdated":1778862643000}'),l={name:"3. 指令/5. 设置指令/SetAxisVibraBLevel.md"};function n(r,a,d,h,o,p){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="setaxisvibrablevel-设置抑振强度等级" tabindex="-1">SetAxisVibraBLevel 设置抑振强度等级 <a class="header-anchor" href="#setaxisvibrablevel-设置抑振强度等级" aria-label="Permalink to &quot;SetAxisVibraBLevel 设置抑振强度等级&quot;">​</a></h1><p>该指令用于设置机器人各关节轴在&quot;自学习振动抑制&quot;功能下的抑振强度等级。它专门针对机械末端在高速运动或频繁启停时产生的物理抖动，通过调整不同轴的抑振强度，在确保生产节拍的同时，最大限度地平稳轨迹并消除机械余震。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetAxisVibraBLevel(AxisID, Level) SetAxisVibraBLevel(轴号, 等级)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>AxisID (轴号)</td><td>枚举型</td><td>指定需要设置抑振等级的具体关节轴，可选范围为 <code>A1</code> 至 <code>A6</code>。</td><td></td></tr><tr><td>Level (等级)</td><td>枚举型</td><td>设置抑振的强弱程度。<br>* <code>Highest</code> (最高)：抑振效果最强，动作最平稳。<br>* <code>High</code> (中高)：较强的抑振效果。<br>* <code>Default</code> (标准)：平衡抑振效果与响应速度。<br>* <code>Low</code> (中低)：较弱的抑振干预。<br>* <code>Lowest</code> (最低)：最小程度的抑振处理。</td><td></td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>自学习振动抑制功能通过识别机械结构的谐振频率，并在伺服控制环路中加入反向补偿信号。该指令设定的等级决定了滤波器对振动信号的增益强度。选择 <code>Highest</code> 时，系统会通过更精细的扭矩补偿来抵消抖动，适合末端负载大或刚性不足的场景；选择 <code>Lowest</code> 则更侧重于保持轴的原始动态刚性。</p><hr><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 为 1 轴设置标准的振动抑制等级</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetAxisVibraBLevel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;A1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Default&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 为 4 轴（腕部轴）设置最高等级的抑振，以消除末端工具的晃动</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetAxisVibraBLevel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;A4&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Highest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><hr><h2 id="执行结果" tabindex="-1">执行结果 <a class="header-anchor" href="#执行结果" aria-label="Permalink to &quot;执行结果&quot;">​</a></h2><p>指令执行后，指定的轴将立即更新其内部抑振算法的权重。在后续执行运动指令（如 <code>MovL</code> 或 <code>MovJ</code>）时，机器人末端在到达目标点停止时的晃动幅度会根据设定的等级发生改变，高等级设置下停稳速度更快且更平滑。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>精密工艺</strong>：在点胶、焊接等工艺中，通过设置 <code>Highest</code> 等级，确保机器人在拐角和启停处不产生抖动，避免胶线变形或焊偏。</li><li><strong>长臂展机型优化</strong>：大臂展机器人在高速停止时易产生低频晃动，为 A2、A3 轴设置高抑振等级可有效改善此问题。</li><li><strong>节拍优化</strong>：当负载极轻且追求极致循环时间时，可将等级设为 <code>Low</code>，以减少算法处理开销，获得更灵敏的响应。</li></ul>`,19)])])}const k=e(l,[["render",n]]);export{b as __pageData,k as default};
